 98→func timeAgo(t time.Time) string {
 99→	if t.IsZero() {
100→		return "never"
101→	}
102→	d := time.Since(t)
103→	switch {
104→	case d < time.Minute:
105→		return "just now"
106→	case d < time.Hour:
107→		return fmt.Sprintf("%dm ago", int(d.Minutes()))
108→	case d < 24*time.Hour:
109→		return fmt.Sprintf("%dh ago", int(d.Hours()))
110→	default:
111→		return fmt.Sprintf("%dd ago", int(d.Hours()/24))
112→	}
113→}
