294→func (m memoriesModel) updateAddForm(msg tea.KeyMsg) (memoriesModel, tea.Cmd) {
295→	switch {
296→	case key.Matches(msg, memoriesKeyMap.Escape):
297→		m.addMode = false
298→		return m, nil
299→
300→	case msg.String() == "tab":
301→		// Blur current, advance focus, focus next
302→		m.addFields[m.addFocus].Blur()
303→		m.addFocus = (m.addFocus + 1) % len(m.addFields)
304→		m.addFields[m.addFocus].Focus()
305→		return m, textinput.Blink
306→
307→	case msg.String() == "shift+tab":
308→		m.addFields[m.addFocus].Blur()
309→		m.addFocus = (m.addFocus + len(m.addFields) - 1) % len(m.addFields)
310→		m.addFields[m.addFocus].Focus()
311→		return m, textinput.Blink
312→
313→	case msg.String() == "enter":
314→		if m.addFocus < len(m.addFields)-1 {
315→			// Not on last field -- advance to next
316→			m.addFields[m.addFocus].Blur()
317→			m.addFocus++
318→			m.addFields[m.addFocus].Focus()
319→			return m, textinput.Blink
320→		}
321→		// On last field -- submit
322→		input := memoryloop.ManualRecordInput{
323→			Kind:       memoryloop.Kind(m.addFields[0].Value()),
324→			Title:      m.addFields[1].Value(),
325→			Body:       m.addFields[2].Value(),
326→			ScopeKind:  memoryloop.ScopeKind(m.addFields[3].Value()),
327→			ScopeValue: "",
328→		}
329→		m.addMode = false
330→		return m, func() tea.Msg { return addMemoryMsg{input: input} }
331→	}
332→
333→	// Delegate to the focused text input for character input
334→	var cmd tea.Cmd
335→	m.addFields[m.addFocus], cmd = m.addFields[m.addFocus].Update(msg)
336→	return m, cmd
337→}
